import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import api from "../api";

function Profile() {
  const params = useParams();
  const loggedInUserId = Number(localStorage.getItem("userId"));
  const profileUserId = params.userId
    ? Number(params.userId)
    : loggedInUserId;

  const isOwnProfile = profileUserId === loggedInUserId;

  const [editMode, setEditMode] = useState(false);
  const [role, setRole] = useState("");

  const [profile, setProfile] = useState({
    full_name: "",
    email: "",
    phone: "",
    batch: "",
    company: "",
    designation: "",
    profile_image: null,
  });

  const [imageFile, setImageFile] = useState(null);
  const [preview, setPreview] = useState(null);

  /* ================= FETCH PROFILE ================= */
  useEffect(() => {
    api.get(`/profile/${profileUserId}`).then((res) => {
      setRole(res.data.role);
      setProfile({
        full_name: res.data.full_name || "",
        email: res.data.email || "",
        phone: res.data.phone || "",
        batch: res.data.batch || "",
        company: res.data.company || "",
        designation: res.data.designation || "",
        profile_image: res.data.profile_image || null,
      });
    });
  }, [profileUserId]);

  /* ================= SAVE PROFILE (OWN ONLY) ================= */
  const saveProfile = () => {
    if (!profile.full_name.trim()) {
      alert("Name cannot be empty");
      return;
    }

    const formData = new FormData();
    formData.append("full_name", profile.full_name);
    formData.append("phone", profile.phone);
    formData.append("batch", profile.batch);
    formData.append("company", profile.company);
    formData.append("designation", profile.designation);

    if (imageFile) {
      formData.append("image", imageFile);
    }

    api.put(`/profile/${loggedInUserId}`, formData).then(() => {
      alert("Profile updated");
      setEditMode(false);

      if (imageFile) {
        setProfile({
          ...profile,
          profile_image: preview,
        });
        setImageFile(null);
      }
    });
  };

  const handleChange = (field, value) => {
    setProfile({ ...profile, [field]: value });
  };

  return (
    <div className="profile-page">
      <div className="profile-card glass">
        <h2>{isOwnProfile ? "My Profile" : "Profile"}</h2>

        {/* ===== AVATAR ===== */}
        <div className="profile-avatar-lg">
          {preview || profile.profile_image ? (
            <img
              src={
                preview ||
                `http://localhost:5000${profile.profile_image}`
              }
              alt="profile"
            />
          ) : (
            <svg viewBox="0 0 24 24">
              <circle cx="12" cy="8" r="4" />
              <path d="M4 20c0-4 4-6 8-6s8 2 8 6" />
            </svg>
          )}
        </div>

        {/* CHANGE PHOTO (OWN PROFILE ONLY) */}
        {editMode && isOwnProfile && (
          <label className="change-photo">
            Change photo
            <input
              type="file"
              hidden
              accept="image/*"
              onChange={(e) => {
                setImageFile(e.target.files[0]);
                setPreview(URL.createObjectURL(e.target.files[0]));
              }}
            />
          </label>
        )}

        {/* ===== VIEW MODE ===== */}
        {!editMode && (
          <div className="profile-info">
            <p><strong>Name:</strong> {profile.full_name}</p>
            <p><strong>Email:</strong> {profile.email}</p>

            {isOwnProfile && (
              <p><strong>Phone:</strong> {profile.phone}</p>
            )}

            <p><strong>Batch:</strong> {profile.batch}</p>

            {role === "ALUMNI" && (
              <>
                <p><strong>Company:</strong> {profile.company}</p>
                <p><strong>Designation:</strong> {profile.designation}</p>
              </>
            )}

            {isOwnProfile && (
              <button
                className="edit-btn"
                onClick={() => setEditMode(true)}
              >
                Edit Profile
              </button>
            )}
          </div>
        )}

        {/* ===== EDIT MODE (OWN PROFILE ONLY) ===== */}
        {editMode && isOwnProfile && (
          <div className="profile-inputs">
            <input
              placeholder="Full name"
              value={profile.full_name}
              onChange={(e) =>
                handleChange("full_name", e.target.value)
              }
            />

            <input
              placeholder="Phone number"
              value={profile.phone}
              onChange={(e) =>
                handleChange("phone", e.target.value)
              }
            />

            <input
              placeholder="Batch year"
              value={profile.batch}
              onChange={(e) =>
                handleChange("batch", e.target.value)
              }
            />

            {role === "ALUMNI" && (
              <>
                <input
                  placeholder="Company"
                  value={profile.company}
                  onChange={(e) =>
                    handleChange("company", e.target.value)
                  }
                />

                <input
                  placeholder="Designation"
                  value={profile.designation}
                  onChange={(e) =>
                    handleChange("designation", e.target.value)
                  }
                />
              </>
            )}

            <button className="save-btn" onClick={saveProfile}>
              Save Changes
            </button>

            <button
              className="cancel-btn"
              onClick={() => {
                setEditMode(false);
                setPreview(null);
              }}
            >
              Cancel
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Profile;
